import os,subprocess

def index_rows(env=None):
    records={}
    for row in subprocess.check_output(['git','ls-files','--stage','-z'],env=env).split(b'\\0'):
        if row:
            meta,path=row.split(b'\\t',1)
            if meta.split()[-1]==b'0':
                records[path]=meta
    return records
before=index_rows(dict(os.environ,GIT_INDEX_FILE='/home/drx/.cache/mipstarre-dev/pr488-refresh-repair-orc-484-20260909-02/index.before'))
after=index_rows()
assert all(after.get(path)==meta for path,meta in before.items())
print('Post-commit preservation: all', len(before),'original stage-0 entries retained.')
